import sys
from itertools import product

n, k, l = map(int, sys.stdin.read().split()[:3])
best = -1
if k > 10:
    # too many places to enumerate: b buys, l sells, rest idle; need b >= l - n and b + l <= k
    lo = max(0, l - n)
    hi = k - l
    if lo <= hi:
        best = n + hi
    print(best)
    sys.exit()
for acts in product('BSN', repeat=k):
    if acts.count('S') != l:
        continue
    cur = n
    peak = n
    ok = True
    for a in acts:
        if a == 'B':
            cur += 1
        elif a == 'S':
            if cur == 0:
                ok = False
                break
            cur -= 1
        peak = max(peak, cur)
    if ok:
        best = max(best, peak)
print(best)

